-- Resources content for the Bookings capacity corrections (CLAUDE.md, "Resources stay in
-- step with the code"). Content only; the schema is 20261007160000_bookings_capacity_rules.sql.

select private.rc_release_guide(
  p_slug => 'bookings-calendar',
  p_tool_key => 'bookings',
  p_title => 'The calendar and the term plan',
  p_summary => 'The term plan''s two envelopes, each pool''s units and windows, blackouts, holds, bookings and reserved blocks, and the booking rule.',
  p_screen_keys => array['bookings.calendar'],
  p_sort_order => 30,
  p_version_note => 'Capacity corrections: a reserve share per class, terms resolved by date, closed terms final',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"Calendar","marks":[{"type":"bold"}]},{"type":"text","text":" tab shows one term of production work: what WUWF has kept for itself, what partners have booked, and how much of the term's capacity is left. Everything on it is measured in professional hours; a project day is eight."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The term plan"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The Director of Operations creates a term plan from "},{"type":"text","text":"Term plan","marks":[{"type":"bold"}]},{"type":"text","text":": the term's dates, the airtime minutes a week the station contributes, and, for each labor class, the hours it has available for production work, an optional reserve share of them, its headcount and its hours a day. Terms can be active together as long as their dates do not overlap, and a date books against the term it falls in. A closed term is final: its figures cannot change, nothing new books into it, and a correction is a new term plan."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Each pool (studio, field, live, edit) has its units for the term and the windows a booking may take, such as a studio morning or afternoon. Select "},{"type":"text","text":"Edit","marks":[{"type":"bold"}]},{"type":"text","text":" on a pool's row to change them."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The two envelopes"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Production capacity","marks":[{"type":"bold"}]},{"type":"text","text":" shows the hours available, the reserve left for strategic work, what is spoken for (bookings and holds) and open capacity. Open capacity is the hours available minus the reserve, minus holds, minus the other bookings. A class with no reserve share, such as the student crew, has no reserve: every booking of it draws open capacity. Open the month table to see how it is spread across the term."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Airtime envelope","marks":[{"type":"bold"}]},{"type":"text","text":" is read from On Air's clocks: the avails marked as admitting a university announcement, the minutes the station already pins there, the contributed envelope from the term plan, and what is left for Traffic to sell. Airtime is placed in Traffic or On Air, never here."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Blackouts, holds, bookings and reserved blocks"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"blackout","marks":[{"type":"bold"}]},{"type":"text","text":" closes dates to partner work on some or every pool, with a reason; one that spans two terms is kept once for each. A "},{"type":"text","text":"hold","marks":[{"type":"bold"}]},{"type":"text","text":" is WUWF's own use of one window, core work or maintenance, and takes the lead's hours for that day. The director adds both with "},{"type":"text","text":"+ Blackout","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"+ Hold","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"booking","marks":[{"type":"bold"}]},{"type":"text","text":" is a partner's hold on one window. The production lead or the director adds one with "},{"type":"text","text":"+ Booking","marks":[{"type":"bold"}]},{"type":"text","text":". A tentative booking holds the window for 14 days and counts as taken; confirm it or release it from the list under the calendar."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Find a slot","marks":[{"type":"bold"}]},{"type":"text","text":" runs the booking rule for a window without booking it, and names the nearest open windows when the one asked for is not available."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"reserved block","marks":[{"type":"bold"}]},{"type":"text","text":" is a window an approved agreement holds for its partner, shown with a dotted frame until the partner's request takes it. Other partners cannot book it until its release deadline; the director keeps or releases blocks from the agreement's page under Partners."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The booking rule"}]},{"type":"paragraph","content":[{"type":"text","text":"Every booking is checked in this order: the date is not blacked out or held for WUWF; the window is not reserved for another partner under an agreement; the window is free, with tentative bookings and reserved blocks counted as taken; the lead's day has room for the hours; and the pricing has capacity. A strategic booking draws the reserve; an incremental or external one draws open capacity. A booking that would take more than half of a month's remaining open hours warns but is not refused. Only the Executive Director can record an exception, and each one is written to the audit log."}]}]}$body$
);

select private.rc_release_note(
  p_slug => 'release-2026-10-07-bookings-capacity-rules',
  p_tool_key => 'bookings',
  p_released_on => '2026-10-07',
  p_title => 'Bookings: a reserve share per class, and terms that book by date',
  p_guide_slugs => array['bookings-calendar'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The reserve share is now set per labor class on the term plan, so the student crew is never limited by it; leave the share blank for a class with none. Terms can be active together when their dates do not overlap, a date books against the term it falls in, and a blackout across two terms is kept once for each. A closed term plan is final."}]}]}$body$
);
